import numpy as np
def equation(eps, T, params):
    return (params[0] + params[1]*np.log(T) + params[2]*T + params[3]*T**3 + params[4]*np.sqrt(eps)
            + params[5]*eps + params[6]*eps**2 + params[7]*T**3*np.log(eps) + params[8]*T**2*np.sqrt(eps)
            + params[9]*eps**2/T)
